declaration:
FUNCTION_BLOCK FB_Task
VAR_INPUT
    Start : BOOL;
    Stop : BOOL;
    Fault : BOOL;
    Reset : BOOL;
END_VAR
VAR_OUTPUT
    Run : BOOL;
    Locked : BOOL;
    Attempts : USINT := 0;
END_VAR
VAR
State : USINT := 0;
    FreeScans : USINT := 0;
END_VAR

implementation:
IF Reset AND NOT Fault AND NOT Start THEN
    State := 0; Attempts := 0; FreeScans := 0;
ELSIF State = 3 THEN
    State := 3;
ELSIF Stop THEN
    State := 0; FreeScans := 0;
ELSE
    CASE State OF
        0: IF Start AND NOT Fault THEN State := 1; END_IF;
        1: IF Fault THEN
            FreeScans := 0;
            IF Attempts < 2 THEN State := 2; ELSE State := 3; END_IF;
           END_IF;
        2: IF Fault THEN FreeScans := 0; ELSE FreeScans := FreeScans + 1; END_IF;
           IF FreeScans >= 2 THEN
               Attempts := Attempts + 1; State := 1; FreeScans := 0;
           END_IF;
    END_CASE;
END_IF;
Run := State = 1; Locked := State = 3;
